(function(){"use strict";app.factory("cuentaPorPagarService",function(t){const o=t.get("mainService"),n="Contabilidad/CuentaPorPagar/",e={get:function(t){let e={...t,tipo:"tipo"in t?t.tipo:1};return o.getData("get",`${n}?json=${JSON.stringify(e)}`,null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let o=JSON.parse(t.payload)||[];if(console.log(o),1===e.tipo)return o[0];5===e.tipo&&console.log(o)}})}};return e})})(window.angular);